INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Backflip Chair', 'backflip-chair', b.id, 'Designed by Gudmundur Ludvik, Backflip is a flexible versatile chair for everyday use, its design allowing it to be easily stored, hung, or brought out and placed as needed, without compromising on comfort or appearance. Balancing aesthetics and technical performance, it is shaped by a clear focus on function and ergonomics, with form emerging from its materials and construction. Crafted in solid wood with a moulded plywood backrest, its simple appearance conceals a refined mechanism within the backrest, allowing the chair to fold and unfold in a smooth motion – bringing flexibility and ease of use. Available in natural beech in a range of coloured finishes, it fits easily into both private and public settings, for daily or occasional use.', 'H78 x W48 x L53.5', 'shell: Golden Lacquered Beech, frame: Golden Lacquered Solid beech', 'https://www.hay.com/hay/furniture/seating/chair/backflip-chair', 'https://www.hay.com/img_20260629022248/globalassets/inriver/integration/service/backflip-chair_910x1100_brandmodel.jpg?w=600', 'chair', 'Gudmundur Ludvik', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Backflip Wall Bracket', 'backflip-wall-bracket', b.id, 'A simple wall bracket designed to hold the Backflip Chair. Two horizontal rods support the chair when hung, offering space-efficient storage for up to two chairs. Made in beech and available in different finishes.', 'H8 x W53 x L17', NULL, 'https://www.hay.com/hay/furniture/seating/seating-accessory/backflip-wall-bracket', 'https://www.hay.com/img_20260629022415/globalassets/inriver/integration/service/backflip-wall-bracket_910x1100_brandmodel.jpg?w=600', 'accessory', 'Gudmundur Ludvik', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 10 Stool', 'chisel-10-stool', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 10 Stool is part of a timeless collection of wooden furniture with a distinctly contemporary expression. Born from an appreciation for wood and its inherent properties, the stool has been developed with careful attention to detail and comfort. Designed with optimal craftmanship and ergonomics in mind, the stool’s soft, organic seat is complemented by angled legs with characteristically bevelled edges that subtly reference the tool behind its name. Chisel’s wide variety of wood types and colours make it ideal for use in most domestic and public settings, from kitchens and dining areas to bedrooms, hallways, and caf&#233;s.', 'H46 x W42 x L40', 'shell: Lacquered Oak veneer, frame: Lacquered Oak veneer', 'https://www.hay.com/hay/furniture/seating/stool/chisel-10-stool', 'https://www.hay.com/img_20260629023348/globalassets/inriver/integration/service/chisel-10-stool_910x1100_brandmodel.jpg?w=600', 'stool', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 20 Table Round', 'chisel-20-table-round', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 20 Table is part of a timeless collection of wooden furniture with a distinctly contemporary look. Born from an appreciation for wood and its inherent properties, the table has been developed with careful attention to detail and construction. Shaped through careful craftsmanship and structural consideration, the circular tabletop is complemented by three angled legs with characteristically bevelled edges that subtly reference the tool behind its name. Available in different wood finishes and sizes, the table’s adaptable design makes it suitable for a range of domestic and public settings – from dining areas and kitchens to caf&#233;s and meeting spaces.', 'H74 x W90 x L90', 'tabletop: Lacquered Oak veneer, frame: Lacquered Oak', 'https://www.hay.com/hay/furniture/tables/dining-table/chisel-20-table-round', 'https://www.hay.com/img_20260630013312/globalassets/inriver/integration/service/chisel-20-table-round_910x1100_brandmodel.jpg?w=600', 'table', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 25 Table Round', 'chisel-25-table-round', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 25 Table is part of a timeless collection of wooden furniture with a distinctly contemporary look. Born from an appreciation for wood and its inherent properties, the table has been developed with careful attention to detail and construction. Shaped through careful craftsmanship and structural consideration, the circular tabletop is complemented by four angled legs with characteristically bevelled edges that subtly reference the tool behind its name. Available in different wood finishes and sizes, the table’s adaptable design makes it suitable for a range of domestic and public settings – from dining areas and kitchens to caf&#233;s and meeting spaces.', 'H74 x W110 x L110', 'tabletop: Lacquered Oak veneer, frame: Lacquered Oak', 'https://www.hay.com/hay/furniture/tables/dining-table/chisel-25-table-round', 'https://www.hay.com/img_20260630013441/globalassets/inriver/integration/service/chisel-25-table-round_910x1100_brandmodel.jpg?w=600', 'table', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 29 Table Round', 'chisel-29-table-round', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 29 Table is part of a timeless collection of wooden furniture with a distinctly contemporary look. Born from an appreciation for wood and its inherent properties, the table has been developed with careful attention to detail and construction. Shaped through careful craftsmanship and structural consideration, the circular tabletop is supported by a central column with characteristically bevelled edges that subtly reference the tool behind its name. Available in different wood finishes and sizes, the table’s adaptable design makes it suitable for a range of domestic and public settings – from dining areas and kitchens to caf&#233;s and meeting spaces.', 'H74 x W90 x L90', 'tabletop: Lacquered Oak veneer, frame: Lacquered Oak', 'https://www.hay.com/hay/furniture/tables/dining-table/chisel-29-table-round', 'https://www.hay.com/img_20260629023513/img_20260629023513/globalassets/inriver/integration/service/chisel-29-table-round_910x1100_brandmodel.jpg?w=600', 'table', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 30 Bar Stool', 'chisel-30-bar-stool', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 30 Bar Stool is part of a timeless collection of wooden furniture with a distinctly contemporary expression. Born from an appreciation for wood and its inherent properties, the bar stool has been developed with careful attention to detail and comfort. Designed with optimal craftmanship and ergonomics in mind, complemented by long, angled legs with characteristically bevelled edges that subtly reference the tool behind its name. With two height options and a wide variety of wood types, colours, and upholsteries, Chisel is ideal for use in most domestic and public settings, from kitchen islands and home bars to caf&#233;s and hotels.', 'H65 x W42 x L40', 'frame: Lacquered Oak veneer', 'https://www.hay.com/hay/furniture/seating/bar-stool/chisel-30-bar-stool', 'https://www.hay.com/img_20260629024442/globalassets/inriver/integration/service/chisel-30-bar-stool_910x1100_brandmodel.jpg?w=600', 'bar-stool', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 30 Table Rectangular', 'chisel-30-table-rectangular', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 30 Table is part of a timeless collection of wooden furniture with a distinctly contemporary look. Born from an appreciation for wood and its inherent properties, the table has been developed with careful attention to detail and construction. Shaped through careful craftsmanship and structural consideration, the rectangular tabletop is complemented by four angled legs positioned in each corner, the characteristically bevelled edges subtly referencing the tool behind its name. Available in different wood finishes and sizes, the table’s generous proportions make it well-suited for shared dining and larger gatherings in both domestic and public settings – from dining rooms and kitchens to caf&#233;s and meeting spaces.', 'H74 x W200 x L95', 'tabletop: Lacquered Oak veneer, frame: Lacquered Oak', 'https://www.hay.com/hay/furniture/tables/dining-table/chisel-30-table-rectangular', 'https://www.hay.com/img_20260629024809/globalassets/inriver/integration/service/chisel-30-table-rectangular_1220x1220_brandmodel.jpg?w=600', 'table', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 35 Bar Stool', 'chisel-35-bar-stool', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 35 Bar Stool with backrest is part of a timeless collection of wooden furniture with a distinctly contemporary expression. Born from an appreciation for wood and its inherent properties, the bar stool has been developed with careful attention to detail and comfort. Designed with optimal craftmanship and ergonomics in mind, the stool’s soft, organic seat and backrest provide good support, complemented by long, angled legs with characteristically bevelled edges that subtly reference the tool behind its name. With two height options and a wide variety of wood types, colours, and upholsteries, Chisel is ideal for use in most domestic and public settings, from kitchen islands and home bars to caf&#233;s and hotels.', 'H87.3 x W48 x L49', 'frame: Lacquered Oak veneer', 'https://www.hay.com/hay/furniture/seating/bar-stool/chisel-35-bar-stool', 'https://www.hay.com/img_20260629025741/globalassets/inriver/integration/service/chisel-35-bar-stool_910x1100_brandmodel.jpg?w=600', 'bar-stool', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 630 Extendable Table Rectangular', 'chisel-630-extendable-table-rectangular', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 630 Extendable Table is part of a timeless collection of wooden furniture with a distinctly contemporary look. Born from an appreciation for wood and its inherent properties, the table has been developed with careful attention to detail and construction. Shaped through careful craftsmanship and structural consideration, the rectangular tabletop is complemented by four angled legs positioned in each corner, the characteristically bevelled edges subtly referencing the tool behind its name. Available in different wood finishes and sizes, the table’s additional leaf extends the tabletop, making it ideal for shared dining and larger gatherings in both domestic and public settings – from dining rooms and kitchens to caf&#233;s and meeting spaces.', 'H74 x W180 x L95', NULL, 'https://www.hay.com/hay/furniture/tables/dining-table/chisel-630-extendable-table-rectangular', 'https://www.hay.com/img_20260629031137/globalassets/inriver/integration/service/chisel-630-extendable-table-rectangular_1220x1220_brandmodel.jpg?w=600', 'table', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 65 Chair', 'chisel-65-chair', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 65 Chair is part of a timeless collection of wooden furniture with a distinctly contemporary expression. Born from an appreciation for wood and its inherent properties, the chair has been developed with careful attention to detail and comfort. Designed with optimal craftmanship and ergonomics in mind, the chair’s soft, organic seat and backrest provide good support, complemented by angled legs with characteristically bevelled edges that subtly reference the tool behind its name. Chisel’s wide variety of wood types, colours, and front upholstery options, combined with its compact size makes it ideal for use in most domestic and public settings, from kitchens and dining rooms to restaurants and educational institutions.', 'H79.8 x W48 x L51.5', 'shell: Oiled Oak veneer, frame: Oiled Oak veneer', 'https://www.hay.com/hay/furniture/seating/chair/chisel-65-chair', 'https://www.hay.com/img_20260629030655/img_20260629030655/globalassets/inriver/integration/service/chisel-65-chair_910x1100_brandmodel.jpg?w=600', 'chair', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Chisel 85 Lounge Chair', 'chisel-85-lounge-chair', b.id, 'Designed for HAY by Norwegian designer Andreas Bergsaker, Chisel 85 Lounge Chair is part of a timeless collection of wooden furniture with a distinctly contemporary expression. Born from an appreciation for wood and its inherent properties, the chair has been developed with careful attention to detail and comfort. Designed with optimal craftmanship and ergonomics in mind, the chair’s soft, organic seat and backrest provide good support, complemented by angled legs with characteristically bevelled edges that subtly reference the tool behind its name. Chisel’s wide variety of wood types, colours and front upholstery options, combined with its compact size makes it ideal for use in most domestic and public settings, from living rooms and bedrooms to waiting rooms, lobbies, and libraries.', 'H68 x W63 x L66', 'shell: Water-based lacquered Moulded walnut veneer, upholstery: None, frame: Water-based lacquered', 'https://www.hay.com/hay/furniture/seating/lounge/chisel-85-lounge-chair', 'https://www.hay.com/img_20260811090355/globalassets/inriver/integration/service/chisel-85-lounge-chair_910x1100_brandmodel.jpg?w=600', 'lounge', 'Andreas Bergsaker', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Mags Soft 2,5 Seater Low armrest with removable cover Combination 1', 'mags-soft-25-seater-low-armrest-with-removable-cover-combination-1', b.id, 'Designed with maximum comfort and minimal details, this Mags Soft Sofa Low Armrest variant features a removable cover, combining a tight expression with deep seats and low armrests, creating an open feel for optimal relaxation. The replaceable upholstery enhances flexibility, durability, and ease of maintenance, with Velcro attachments allowing for simple removal and reattachment without tools, while enabling the look to be refreshed over time. Carefully selected textiles with tonal stitching ensure a cohesive finish while offering numerous customisation possibilities. The modular system allows for both compact and expansive seating arrangements, with pre-defined combinations that make it a versatile choice for a wide range of domestic and contract settings.', NULL, NULL, 'https://www.hay.com/hay/furniture/seating/sofa/mags-soft-25-seater-low-armrest-with-removable-cover-combination-1', 'https://www.hay.com/img_20260629054803/globalassets/inriver/integration/service/mags-soft-25-seater-low-armrest-with-removable-cover-combination-1_1380x900_brandmodel.jpg?w=600', 'sofa', NULL, NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
