INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Mags Soft with Removable Cover S01RC', 'mags-soft-with-removable-cover-s01rc', b.id, 'Designed with maximum comfort and minimal details, this Mags Soft Sofa Low Armrest variant features a removable cover, combining a tight expression with deep seats and low armrests, creating an open feel for optimal relaxation. The replaceable upholstery enhances flexibility, durability, and ease of maintenance, with Velcro attachments allowing for simple removal and reattachment without tools, while enabling the look to be refreshed over time. Carefully selected textiles with tonal stitching ensure a cohesive finish while offering numerous customisation possibilities. The modular system allows for both compact and expansive seating arrangements, with pre-defined combinations that make it a versatile choice for a wide range of domestic and contract settings.', NULL, NULL, 'https://www.hay.com/hay/furniture/seating/sofa/mags-soft-with-removable-cover-s01rc', 'https://www.hay.com/img_20260811025134/globalassets/inriver/integration/service/mags-soft-with-removable-cover-s01rc_brandmodel.jpg?w=600', 'sofa', NULL, NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Mimi 1 Seater', 'mimi-1-seater', b.id, 'Designed by Philippe Malouin, Mimi is an inviting sofa defined by the interplay between precise structure and a fluid silhouette. Its concise, sculpted contours are softened by gently draped upholstery, giving the design a relaxed yet refined expression. A generous central cushion provides comfort, while the tailored cover falls over the frame like a softly draped blanket, creating a balanced contrast between form and softness. Precise stitching along the upper edges emphasises the sofa’s defined outline before gradually loosening into a skirted base, where the fabric flows more freely. This subtle transition also signals the removable over, emphasising Mimi’s adaptable and long-lasting design. Developed for flexible use, the cover can be removed and replaced, allowing the appearance to evolve over time. Available in multiple sizes and as an ottoman, Mimi comes in a curated selection of fabrics and can be complemented with matching square or rectangular cushions for added comfort. ', 'H76 x W93 x L95', NULL, 'https://www.hay.com/hay/furniture/seating/lounge/mimi-1-seater', 'https://www.hay.com/img_20260629040111/globalassets/inriver/integration/service/mimi-1-seater_910x1100_brandmodel.jpg?w=600', 'lounge', 'Philippe Malouin', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
