INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Mimi 2 Seater', 'mimi-2-seater', b.id, 'Designed by Philippe Malouin, Mimi is an inviting sofa defined by the interplay between precise structure and a fluid silhouette. Its concise, sculpted contours are softened by gently draped upholstery, giving the design a relaxed yet refined expression. A generous central cushion provides comfort, while the tailored cover falls over the frame like a softly draped blanket, creating a balanced contrast between form and softness. Precise stitching along the upper edges emphasises the sofa’s defined outline before gradually loosening into a skirted base, where the fabric flows more freely. This subtle transition also signals the removable over, emphasising Mimi’s adaptable and long-lasting design. Developed for flexible use, the cover can be removed and replaced, allowing the appearance to evolve over time. Available in multiple sizes and as an ottoman, Mimi comes in a curated selection of fabrics and can be complemented with matching square or rectangular cushions for added comfort. ', 'H76 x W160 x L96', NULL, 'https://www.hay.com/hay/furniture/seating/sofa/mimi-2-seater', 'https://www.hay.com/img_20260629040643/globalassets/inriver/integration/service/mimi-2-seater_910x1100_brandmodel.jpg?w=600', 'sofa', 'Philippe Malouin', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Mimi 3 Seater', 'mimi-3-seater', b.id, 'Designed by Philippe Malouin, Mimi is an inviting sofa defined by the interplay between precise structure and a fluid silhouette. Its concise, sculpted contours are softened by gently draped upholstery, giving the design a relaxed yet refined expression. A generous central cushion provides comfort, while the tailored cover falls over the frame like a softly draped blanket, creating a balanced contrast between form and softness. Precise stitching along the upper edges emphasises the sofa’s defined outline before gradually loosening into a skirted base, where the fabric flows more freely. This subtle transition also signals the removable over, emphasising Mimi’s adaptable and long-lasting design. Developed for flexible use, the cover can be removed and replaced, allowing the appearance to evolve over time. Available in multiple sizes and as an ottoman, Mimi comes in a curated selection of fabrics and can be complemented with matching square or rectangular cushions for added comfort. ', 'H76 x W230 x L96', NULL, 'https://www.hay.com/hay/furniture/seating/sofa/mimi-3-seater', 'https://www.hay.com/img_20260629041853/globalassets/inriver/integration/service/mimi-3-seater_910x1100_brandmodel.jpg?w=600', 'sofa', 'Philippe Malouin', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Mimi Cushion', 'mimi-cushion', b.id, 'The Mimi Cushions are designed to enhance the comfort and softness of the Mimi Sofa. Customised to fit the different variants, they are offered in a range of upholstery options to match, creating a cohesive look that can be refreshed over time. The cushions are sold in sets of two or three, with the one-seater version available individually.', 'H15 x W53 x L53', 'color: None', 'https://www.hay.com/hay/accessories/indoor-living/cushions--throws/mimi-cushion', 'https://www.hay.com/img_20260629043648/globalassets/inriver/integration/service/mimi-cushion_910x1100_brandmodel.jpg?w=600', 'accessory', 'Philippe Malouin', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Mimi Ottoman', 'mimi-ottoman', b.id, 'The Mimi Ottoman is a versatile piece that can be used independently or together with the Mimi Sofa. Serving as an extra seat, a casual surface, or a comfortable extension of the sofa, it adapts easily to different uses. The removable cover is offered in a range of upholstery options matching the sofa, allowing for a cohesive look that can be refreshed over time.', 'H45 x W85 x L85', NULL, 'https://www.hay.com/hay/furniture/seating/sofa/mimi-ottoman', 'https://www.hay.com/img_20260629044345/globalassets/inriver/integration/service/mimi-ottoman_910x1100_brandmodel.jpg?w=600', 'ottoman', 'Philippe Malouin', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Pack Chair 10', 'pack-chair-10', b.id, 'Designed for HAY by Jasper Morrison, Pack Chair 10 is a contemporary reinterpretation of the wooden trattoria chair. Its moulded plastic seat and backrest translate a familiar silhouette into an industrial context, while solid oak legs and an optional plywood backrest introduce a natural counterpoint to the form. The seat and backrest are made from 80% post-consumer recycled polypropylene blended with wood fibres, which reinforce the material and lend the surface a subtle, natural tactility. Delivered flat-packed, the chair&#39;s considered construction ensures easy and intuitive assembly. Its refined proportions and considered detailing make it equally at home in residential, retail, and contract settings.', 'H78 x W45 x L45', 'shell: Hull red Polypropylene, frame: Oiled Solid oak', 'https://www.hay.com/hay/furniture/seating/chair/pack-chair/pack-chair-10', 'https://www.hay.com/img_20260629034949/globalassets/inriver/integration/service/pack-chair-10_910x1100_brandmodel.jpg?w=600', 'chair', 'Jasper Morrison', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
INSERT INTO products (name, slug, brand_id, description, dimensions, materials, source_url, image_url, category, designer, created_at, updated_at) SELECT 'Pack Chair 11', 'pack-chair-11', b.id, 'Designed for HAY by Jasper Morrison, Pack Chair 11 is a contemporary reinterpretation of the wooden trattoria chair. Its moulded plastic seat and backrest translate a familiar silhouette into an industrial context, while solid oak legs and an optional plywood backrest introduce a natural counterpoint to the form. The seat and backrest are made from 80% post-consumer recycled polypropylene blended with wood fibres, which reinforce the material and lend the surface a subtle, natural tactility. Delivered flat-packed, the chair&#39;s considered construction ensures easy and intuitive assembly, while the seat cover adds the tailored appearance and comfort of an upholstered seat. Its refined proportions and considered detailing make it equally at home in residential, retail, and contract settings.', NULL, 'frame: Oiled Solid oak', 'https://www.hay.com/hay/furniture/seating/chair/pack-chair/pack-chair-11', 'https://www.hay.com/img_20260629035442/globalassets/inriver/integration/service/pack-chair-11_1220x1220_brandmodel.jpg?w=600', 'chair', 'Jasper Morrison', NOW(), NOW() FROM brands b WHERE b.slug='hay' ON CONFLICT (brand_id, slug) DO NOTHING;
